"""Topology-based whole-residue selection and link hydrogen placement.

Uses sparcleqc's Q1--M1 link-atom construction, with explicit TAQO bond
lengths instead of force-field equilibrium-length ratios. No coordinate
matching or global PyMOL state is used.
"""

import numpy as np


def centroid(coordinates, masses):
    xyz = np.asarray(coordinates, dtype=float)
    weights = np.asarray(masses, dtype=float)
    if xyz.shape != (len(weights), 3) or not len(weights):
        raise ValueError("Expected nonempty N x 3 coordinates and N masses")
    if not np.isfinite(xyz).all() or not np.isfinite(weights).all() or np.any(weights <= 0):
        raise ValueError("Coordinates and positive masses must be finite")
    return np.average(xyz, axis=0, weights=weights)


def link_hydrogen(inside, outside, length):
    q1, m1 = np.asarray(inside), np.asarray(outside)
    distance = np.linalg.norm(m1 - q1)
    if distance < 1e-8 or not np.isfinite(distance) or length <= 0:
        raise ValueError("Invalid boundary bond")
    return q1 + length * (m1 - q1) / distance


def residue_key(residue):
    return f"{residue.chain.id}:{residue.id}:{residue.insertionCode}"


def select_residues(topology, xyz_angstrom, center, radius):
    if not np.isfinite(radius) or radius <= 0:
        raise ValueError("Pocket radius must be positive and finite")
    return [
        residue_key(res)
        for res in topology.residues()
        if any(
            atom.element.symbol != "H"
            and np.linalg.norm(xyz_angstrom[atom.index] - center) <= radius
            for atom in res.atoms()
        )
    ]


def cap_boundary(inside_atom, outside_atom, xyz):
    """Reject unsupported cuts rather than silently inventing chemistry."""
    pair = (inside_atom.name, outside_atom.name)
    if pair == ("N", "C"):
        length = 1.01
    elif pair == ("C", "N"):
        length = 1.09
    elif pair == ("SG", "SG"):
        length = 1.34
    else:
        raise ValueError(f"Unsupported pocket boundary bond: {pair}")
    return link_hydrogen(xyz[inside_atom.index], xyz[outside_atom.index], length)

"""Versioned CDK2 pilot: immutable inputs, explicit chemical matching, nine model passes.

Initialize in cdsg-prep, score in qcml, analyze in cdsg-prep. Never writes the
legacy apnet result directory or the live dashboard.
"""

import argparse
import csv
import json
import shutil
import subprocess
import time
from datetime import UTC, datetime
from pathlib import Path

import numpy as np

from .template import sha256

TAGS = ([f"ap2-member-{i}" for i in range(5)]
        + [f"ap3d3-base-seed{i}" for i in range(42, 46)])


def read_csv(path):
    with Path(path).open(newline="") as handle:
        return list(csv.DictReader(handle))


def write_csv(path, rows):
    if not rows:
        raise ValueError("Refusing to write empty table")
    with Path(path).open("w", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def write_json(path, value):
    Path(path).write_text(json.dumps(value, indent=2, allow_nan=False) + "\n")


def git_revision(path):
    return subprocess.check_output(["git", "-C", str(path), "rev-parse", "HEAD"],
                                   text=True).strip()


def init_campaign(root, taqo, manifest):
    from rdkit import Chem

    if (root / "campaign.json").exists():
        raise FileExistsError("Campaign already initialized")
    entry = json.loads(manifest.read_text())["systems"]["cdk2"]
    baseline_sdf = Path.home() / "data/_ext/plb/data/cdk2/02_ligands/ligands.sdf"
    baseline_molecules = list(Chem.SDMolSupplier(str(baseline_sdf), removeHs=False))
    source_molecules = list(Chem.SDMolSupplier(entry["ligands"], removeHs=False))

    def identity(mol):
        if mol is None:
            raise ValueError("Invalid source SDF record")
        return Chem.MolToSmiles(Chem.RemoveHs(mol), isomericSmiles=True)

    baseline_identity = {}
    for mol in baseline_molecules:
        key = identity(mol)
        if key in baseline_identity:
            raise ValueError("Ambiguous baseline chemical identity; review variants explicitly")
        baseline_identity[key] = mol.GetProp("_Name")
    affinity = {r["ligand"]: r for r in read_csv(taqo / "apnet/affinities.csv")
                if r["system_id"] == "cdk2"}
    crosswalk = []
    seen = set()
    for index, mol in enumerate(source_molecules):
        smiles = identity(mol)
        if smiles in seen:
            raise ValueError("Duplicate source chemical identity: pilot requires explicit resolution")
        seen.add(smiles)
        baseline_name = baseline_identity.get(smiles, "")
        old = affinity.get(baseline_name, {})
        crosswalk.append({
            "system_id": "cdk2", "ligand": f"record-{index:04d}", "record_index": index,
            "source_title": mol.GetProp("_Name"), "canonical_isomeric_smiles": smiles,
            "formal_charge": Chem.GetFormalCharge(mol),
            "dg_exp_kcal_mol": float(mol.GetProp("r_exp_dg")),
            "measurement_source": "public source SDF r_exp_dg (kcal/mol)",
            "baseline_ligand": baseline_name,
            "baseline_dg_exp_kcal_mol": old.get("dg_exp_kcal_mol", ""),
            "baseline_scoreable": old.get("scoreable", "0"),
            "match_rule": "exact canonical isomeric SMILES, charge/tautomer retained"
                          if baseline_name else "no exact baseline molecule",
        })
    root.mkdir(parents=True, exist_ok=True)
    write_csv(root / "crosswalk.csv", crosswalk)
    archive = root / "baseline"
    archive.mkdir()
    # Preserve the full baseline rankings and pass provenance, not just current CDK2 tau.
    for relative in ("benchmark_data.json", "benchmark.html", "register_apnet.py",
                     "build_benchmark.py", "benchmark.template.html",
                     "apnet/affinities.csv", "apnet/pocket_inventory.csv",
                     "apnet/receptor_qc.csv", "apnet/scores.csv", "apnet/rankings.csv",
                     "apnet/analyze_rankings.py", "apnet/run_inference.py"):
        dest = archive / relative
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(taqo / relative, dest)
    shutil.copytree(taqo / "apnet/predictions", archive / "apnet/predictions")
    # Preserve original input pockets for future code-controlled comparisons.
    shutil.copytree(taqo / "apnet/pockets/cdk2", archive / "apnet/pockets/cdk2")
    code_root = Path.home() / "gits/qcmlforge__worktrees/mace-apnet"
    model_paths = {
        f"ap2-member-{i}": {
            "atom": str(code_root / f"models/am_ensemble/am_{i}.pt"),
            "pair": str(code_root / f"models/ap2_ensemble/ap2_{i}.pt"),
        } for i in range(5)
    }
    model_paths.update({
        f"ap3d3-base-seed{i}": {
            "pair": str(Path.home() / f"data/PLA15/diagnostic_checkpoints/BASE-seed{i}.pt")
        } for i in range(42, 46)
    })
    source_files = sorted(Path(__file__).parent.glob("*.py"))
    code_copy = root / "preparation_code"
    code_copy.mkdir()
    for path in source_files:
        shutil.copy2(path, code_copy / path.name)
    write_json(root / "source_manifest.json", json.loads(manifest.read_text()))
    campaign = {
        "schema_version": 1, "campaign_id": root.name, "system_id": "cdk2",
        "created_at": datetime.now(UTC).isoformat(),
        "status": "initialized", "n_records": len(crosswalk), "required_passes": TAGS,
        "entry": entry, "crosswalk_sha256": sha256(root / "crosswalk.csv"),
        "baseline_sdf_sha256": sha256(baseline_sdf),
        "model_code_root": str(code_root), "model_code_commit": git_revision(code_root),
        "model_checkpoints": model_paths,
        "model_checkpoint_sha256": {
            tag: {name: sha256(path) for name, path in paths.items()}
            for tag, paths in model_paths.items()
        },
        "baseline_sha256": {
            str(p.relative_to(archive)): sha256(p)
            for p in sorted(archive.rglob("*")) if p.is_file()
        },
        "preparation_code_sha256": {p.name: sha256(p) for p in source_files},
        "note": "New preparation campaign, not a geometry-only ablation or paper-matched subset",
    }
    write_json(root / "campaign.json", campaign)
    print(f"Initialized {len(crosswalk)} records; "
          f"{sum(bool(r['baseline_ligand']) for r in crosswalk)} exact baseline matches")


def validate_prepared(root, campaign):
    if sha256(root / "crosswalk.csv") != campaign["crosswalk_sha256"]:
        raise ValueError("Crosswalk changed after campaign initialization")
    rows = read_csv(root / "crosswalk.csv")
    paths, template_hashes = {}, set()
    for row in rows:
        path = root / "prepared/cdk2" / f"{int(row['record_index']):04d}"
        report = json.loads((path / "preparation.json").read_text())
        if report["status"] != "minimized" or not report["force_tolerance_met"]:
            raise ValueError(f"Unconverged/incomplete preparation: {path}")
        if report["input"] != campaign["entry"]:
            raise ValueError("Prepared input differs from campaign")
        template_hashes.add(report["template_sha256"])
        paths[row["ligand"]] = path / "qcml_molecule.json"
    if len(template_hashes) != 1 or len(paths) != campaign["n_records"]:
        raise ValueError("Inconsistent target template or record count")
    return rows, paths


def score_campaign(root, tag, threads):
    import apnet_pt
    import qcelemental as qcel
    import torch
    from apnet_pt.constants import ALLOWED_ELEMENTS

    campaign = json.loads((root / "campaign.json").read_text())
    rows, paths = validate_prepared(root, campaign)
    code_root = Path(apnet_pt.__file__).resolve().parents[2]
    if str(code_root) != campaign["model_code_root"] or (
        git_revision(code_root) != campaign["model_code_commit"]
    ):
        raise ValueError("Wrong QCML code: prepend campaign model_code_root/src to PYTHONPATH")
    checkpoints = campaign["model_checkpoints"][tag]
    hashes = {name: sha256(path) for name, path in checkpoints.items()}
    if hashes != campaign["model_checkpoint_sha256"][tag]:
        raise ValueError("Model checkpoint changed")
    dest = root / "predictions" / tag
    if dest.exists():
        raise FileExistsError(f"Pass already exists; do not mix/resume stale scores: {dest}")
    torch.set_num_threads(threads)
    torch.manual_seed(42)
    if tag.startswith("ap2"):
        from apnet_pt.AtomPairwiseModels.apnet2 import APNet2Model
        model = APNet2Model(pre_trained_model_path=checkpoints["pair"],
                           atom_model_pre_trained_path=checkpoints["atom"], use_GPU=False)
    else:
        from apnet_pt import model_io
        from apnet_pt.AtomPairwiseModels.apnet3_d3_fused import APNet3D3_AtomType_Model
        checkpoint = model_io.load_checkpoint(checkpoints["pair"], map_location="cpu")
        if not model_io.has_embedded_submodel(checkpoint, "dimer_prop_model"):
            raise ValueError("AP3-D3 checkpoint is not self-contained")
        config = model_io.load_config_from_checkpoint(checkpoint)
        kwargs = {key: config[key] for key in
                  ("n_message", "n_rbf", "n_neuron", "n_embed", "r_cut", "r_cut_im")}
        model = APNet3D3_AtomType_Model(
            pre_trained_model_path=checkpoints["pair"], use_GPU=False,
            use_precomputed_classical=False, ds_root=None, **kwargs,
        )
    for name in ("model", "atom_model", "dimer_prop_model"):
        module = getattr(model, name, None)
        if isinstance(module, torch.nn.Module):
            module.eval()
    predictions, geometry_hashes = [], {}
    start = time.monotonic()
    for row in rows:
        source = paths[row["ligand"]]
        molecule = qcel.models.Molecule(**json.loads(source.read_text()))
        geometry_hashes[row["ligand"]] = sha256(source)
        if set(map(int, molecule.atomic_numbers)) - set(ALLOWED_ELEMENTS):
            raise ValueError(f"Unsupported elements: {row['ligand']}")
        moment = time.monotonic()
        with torch.inference_mode():
            values = np.asarray(model.predict_qcel_mols([molecule], batch_size=1), dtype=float)
        if values.shape != (1, 4) or not np.isfinite(values).all():
            raise ValueError(f"Invalid prediction: {row['ligand']}: {values}")
        predictions.append({
            "system_id": "cdk2", "ligand": row["ligand"], "n_atoms": len(molecule.symbols),
            **dict(zip(["elst", "exch", "ind", "disp"], values[0].tolist())),
            "total": float(values.sum()), "seconds": time.monotonic() - moment,
        })
        print(f"{tag} {row['ligand']}: {values.sum():.5f}", flush=True)
    dest.mkdir(parents=True)
    write_csv(dest / "cdk2.csv", predictions)
    write_json(dest / "provenance.json", {
        "tag": tag, "campaign_sha256": sha256(root / "campaign.json"),
        "checkpoints": checkpoints, "checkpoint_sha256": hashes,
        "molecule_sha256": geometry_hashes, "code_root": str(code_root),
        "code_commit": git_revision(code_root), "driver_sha256": sha256(__file__),
        "n_complexes": len(rows), "wall_seconds": time.monotonic() - start,
        "threads": threads, "device": "cpu", "torch_version": torch.__version__,
        "qcelemental_version": qcel.__version__, "units": "kcal/mol",
        "prediction_sha256": sha256(dest / "cdk2.csv"),
    })


def correlation(reference, predicted):
    from scipy import stats

    if len(reference) < 8 or not np.isfinite([reference, predicted]).all():
        raise ValueError("Insufficient/nonfinite ranking data")
    if len(set(reference)) < 2 or len(set(predicted)) < 2:
        raise ValueError("Constant ranking vector")
    return {
        "n": len(reference),
        "kendall_tau": float(stats.kendalltau(reference, predicted, variant="b").statistic),
        "spearman_rho": float(stats.spearmanr(reference, predicted).statistic),
        "pearson_r": float(stats.pearsonr(reference, predicted).statistic),
    }


def analyze_campaign(root):
    campaign = json.loads((root / "campaign.json").read_text())
    rows, paths = validate_prepared(root, campaign)
    predictions, baseline = {}, {}
    expected = {r["ligand"] for r in rows}
    current_hashes = {key: sha256(path) for key, path in paths.items()}
    for tag in TAGS:
        directory = root / "predictions" / tag
        provenance = json.loads((directory / "provenance.json").read_text())
        if (provenance["molecule_sha256"] != current_hashes
                or provenance["campaign_sha256"] != sha256(root / "campaign.json")
                or provenance["checkpoint_sha256"] != campaign["model_checkpoint_sha256"][tag]
                or provenance["prediction_sha256"] != sha256(directory / "cdk2.csv")):
            raise ValueError(f"Stale provenance: {tag}")
        records = read_csv(directory / "cdk2.csv")
        values = {r["ligand"]: float(r["total"]) for r in records}
        if set(values) != expected or len(records) != len(expected):
            raise ValueError(f"Incomplete/duplicate model pass: {tag}")
        predictions[tag] = values
        baseline[tag] = {r["ligand"]: float(r["total"]) for r in
                         read_csv(root / "baseline/apnet/predictions" / tag / "cdk2.csv")}
    for family, members in [
        ("ap2-ensemble", TAGS[:5]), ("ap3d3-base-ensemble", TAGS[5:]),
    ]:
        predictions[family] = {key: float(np.mean([predictions[m][key] for m in members]))
                               for key in expected}
        old_keys = set(baseline[members[0]])
        if any(set(baseline[m]) != old_keys for m in members):
            raise ValueError("Baseline ensemble members have different coverage")
        baseline[family] = {key: float(np.mean([baseline[m][key] for m in members]))
                            for key in old_keys}
    full, paired = [], []
    for tag, predicted in predictions.items():
        full.append({"run_id": tag, "system_id": "cdk2",
                     **correlation([float(r["dg_exp_kcal_mol"]) for r in rows],
                                   [predicted[r["ligand"]] for r in rows])})
        common = [r for r in rows if r["baseline_scoreable"] == "1"
                  and r["baseline_ligand"] in baseline[tag]]
        ref = [float(r["baseline_dg_exp_kcal_mol"]) for r in common]
        old_stats = correlation(ref, [baseline[tag][r["baseline_ligand"]] for r in common])
        new_stats = correlation(ref, [predicted[r["ligand"]] for r in common])
        paired.append({
            "run_id": tag, "system_id": "cdk2", "n": len(common),
            "baseline_kendall_tau": old_stats["kendall_tau"],
            "prepared_kendall_tau": new_stats["kendall_tau"],
            "delta_kendall_tau": new_stats["kendall_tau"] - old_stats["kendall_tau"],
            "baseline_spearman_rho": old_stats["spearman_rho"],
            "prepared_spearman_rho": new_stats["spearman_rho"],
            "ligands": [r["ligand"] for r in common],
        })
    write_csv(root / "rankings.csv", full)
    write_json(root / "paired_comparison.json", paired)
    write_json(root / "analysis.json", {
        "campaign_id": campaign["campaign_id"], "status": "complete",
        "campaign_sha256": sha256(root / "campaign.json"),
        "rankings_sha256": sha256(root / "rankings.csv"),
        "paired_comparison_sha256": sha256(root / "paired_comparison.json"),
        "n_records": len(rows), "n_passes": len(TAGS), "n_systems": 1,
        "note": "Paired correlations use identical baseline measurements and chemical identities; "
                "full-series correlations use source SDF r_exp_dg. Not a causal minimization ablation.",
    })
    print(json.dumps([r for r in paired if "ensemble" in r["run_id"]], indent=2))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["init", "score", "analyze"])
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--taqo", type=Path, default=Path.home() / "data/TAQO22")
    parser.add_argument("--manifest", type=Path, default=Path("data/manifest.json"))
    parser.add_argument("--tag", choices=TAGS)
    parser.add_argument("--threads", type=int, default=2)
    args = parser.parse_args(argv)
    if args.command == "init":
        init_campaign(args.root, args.taqo, args.manifest)
    elif args.command == "score":
        if not args.tag or args.threads < 1:
            parser.error("score requires --tag and positive --threads")
        score_campaign(args.root, args.tag, args.threads)
    else:
        analyze_campaign(args.root)


if __name__ == "__main__":
    main()

"""Fixed target pocket templates, mapped by residue identity, never atom index."""

import hashlib
import json
from pathlib import Path

from .geometry import residue_key, select_residues


def sha256(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def residue_signature(res):
    return {
        "name": res.name,
        "heavy_atoms": sorted(a.name for a in res.atoms() if a.element.symbol != "H"),
    }


def make_template(topology, xyz, center, radius, source):
    residues = list(topology.residues())
    keys = [residue_key(r) for r in residues]
    if len(keys) != len(set(keys)):
        raise ValueError("Ambiguous residue identities: chain/residue/insertion code must be unique")
    selected = select_residues(topology, xyz, center, radius)
    if not selected:
        raise ValueError("Empty pocket: check reference ligand and receptor coordinate frame")
    return {
        "schema_version": 1,
        "source": source,
        "center_angstrom": list(map(float, center)),
        "radius_angstrom": radius,
        "residues": {residue_key(r): residue_signature(r) for r in residues},
        "selected_residues": selected,
    }


def map_template(template, topology):
    """Fail closed for renumbered/mutated receptors; coordinates may vary."""
    residues = list(topology.residues())
    observed = {residue_key(r): residue_signature(r) for r in residues}
    if len(observed) != len(residues) or observed != template["residues"]:
        raise ValueError(
            "Receptor does not match target template residue/atom identities; "
            "align and consistently renumber it or create a separate template"
        )
    selected = set(template["selected_residues"])
    return {r.index for r in residues if residue_key(r) in selected}


def load_template(path):
    data = json.loads(Path(path).read_text())
    if data.get("schema_version") != 1:
        raise ValueError("Unsupported template schema")
    return data
